/**
 * React hook to access the global TabsController (window[GLOBAL_SYMBOL]).
 * Optionally subscribe to tab switch events via callback. Returns controller methods in stable refs.
 */
import type { Tab } from '../common';
import type { ISelectTabByIdOptions, TabsControllerOptions, TabsHistory } from '../runtime/TabsController';
export type { Tab };
/** Called when user (or code) switches to another tab; receives tab descriptor and optional element id. */
export type UseDiplodocTabsCallback = (tab: Tab, currentTabId?: string) => void;
/**
 * Access tabs API and optionally listen to tab switch events.
 * @param callback - If provided, called on each tab switch (tab, currentTabId).
 * @returns Object with selectTabById, selectTab, configure, restoreTabs, onPageChanged, and persistence helpers.
 */
export declare function useDiplodocTabs(callback?: UseDiplodocTabsCallback | undefined): {
    selectTabById: (tabId: string, options?: ISelectTabByIdOptions) => void;
    selectTab: (tab: Tab) => void;
    configure: (options: Partial<TabsControllerOptions>) => void;
    restoreTabs: (tabsHistory: TabsHistory) => void;
    onPageChanged: () => void;
    getTabsFromLocalStorage: () => TabsHistory;
    getTabsFromSearchQuery: () => TabsHistory;
    getCurrentPageTabHistory: (tabsHistory: TabsHistory) => TabsHistory;
    updateLocalStorageWithTabs: (tabsHistory: TabsHistory) => void;
    updateQueryParamWithTabs: (tabsHistory: TabsHistory) => void;
};
